mapper.select:
SELECT p.*, s.name AS store_name, a.name AS account_name, u.nickname AS create_by_name
FROM chain_franchise_deposit p
LEFT JOIN store_info s ON s.id = p.store_id
LEFT JOIN fin_account a ON a.id = p.account_id
LEFT JOIN sys_user u ON u.id = p.create_by

    p.store_id = #{storeId}
    AND p.kind = #{kind}
    AND p.biz_date >= #{begin}
    AND p.biz_date <= #{end}

        AND p.store_id IN #{sid}


ORDER BY p.biz_date DESC, p.id DESC

SELECT COALESCE(SUM(CASE WHEN p.kind = 'RECEIVE' THEN p.amount ELSE -p.amount END), 0)
FROM chain_franchise_deposit p
WHERE p.store_id = #{storeId}
